/**
 * Markdown → HTML（高级修正版 for Coze拼接结构）
 * ✅ 修复 <p><h3> 嵌套
 * ✅ 支持 “·” 自动转换为 <ul><li>
 * ✅ 支持 ---### / ####Title 格式识别
 * ✅ 输出结构简洁、干净、可嵌入前端
 * ✅ 页面顶部展示来源 URL（来自：$('Loop Over Items').item.json.property_product_url）
 */

const input = $json.output || $json.merged_output || '';
if (!input) {
  return { html_output: '<p><em>No content available.</em></p>' };
}

// 取上一节点输出的 URL，并做安全处理
function sanitizeUrl(u) {
  try {
    const raw = (u || '').toString().trim();
    if (!raw) return '';
    // 仅允许 http / https
    if (!/^https?:\/\//i.test(raw)) return '';
    // 简单属性转义，避免破坏 HTML
    return raw
      .replace(/"/g, '%22')
      .replace(/</g, '%3C')
      .replace(/>/g, '%3E');
  } catch {
    return '';
  }
}

const sourceUrlRaw = $('Loop Over Items')?.item?.json?.property_product_url;
const sourceUrl = sanitizeUrl(sourceUrlRaw);

// Step 1️⃣ 基础预处理
let md = input
  .replace(/\\n/g, '\n')
  .replace(/\\t/g, '  ')
  .replace(/\r\n/g, '\n')
  .replace(/-{3,}\s*###/g, '\n---\n###')
  .replace(/([a-z0-9])####/gi, '$1\n####')
  .replace(/([a-z0-9])###/gi, '$1\n###')
  .replace(/([a-z0-9])##/gi, '$1\n##')
 // .replace(/([a-z0-9])#/gi, '$1\n#')
  .replace(/\n{3,}/g, '\n\n')
  .trim();

// Step 2️⃣ 核心 Markdown → HTML 转换
function markdownToHtml(md) {
  let html = md;

  // 安全转义
  html = html.replace(/</g, '&lt;').replace(/>/g, '&gt;');

  // 分隔线
  html = html.replace(/^---$/gm, '<hr/>');

  // 处理项目符号 “· ”
  html = html.replace(/(?:^|\n)·\s*(.*?)(?=\n|$)/g, '\n<li>$1</li>');
  html = html.replace(/(<li>.*<\/li>)(\s*<li>.*<\/li>)+/g, match => `<ul>${match}</ul>`);

  // FAQ 模式
  html = html.replace(/\*\*Q(\d+)\.\s*(.*?)\*\*/g, '<h4>Q$1. $2</h4>');
  html = html.replace(/A:\s*(.*)/g, '<p><strong>A:</strong> $1</p>');

  // 标题
  html = html.replace(/^#####\s*(.*)$/gm, '<h5>$1</h5>');
  html = html.replace(/^####\s*(.*)$/gm, '<h4>$1</h4>');
  html = html.replace(/^###\s*(.*)$/gm, '<h3>$1</h3>');
  html = html.replace(/^##\s*(.*)$/gm, '<h2>$1</h2>');
  html = html.replace(/^#\s*(.*)$/gm, '<h1>$1</h1>');

  // 加粗
  html = html.replace(/\*\*(.*?)\*\*/g, '<strong>$1</strong>');

  // 段落包装（排除标题、分隔线、ul/li）
  html = html
    .split('\n')
    .map(line => {
      if (/^<h\d|^<hr|^<ul>|^<\/ul>|^<li>|^<\/li>/.test(line.trim())) return line.trim();
      if (!line.trim()) return '';
      return `<p>${line.trim()}</p>`;
    })
    .join('\n');

  // 修正嵌套错误
  html = html
    .replace(/<p><h(\d)>/g, '<h$1>')
    .replace(/<\/h(\d)><\/p>/g, '</h$1>')
    .replace(/<p><hr\/><\/p>/g, '<hr/>')
    .replace(/<\/ul>\s*<ul>/g, '')
    .trim();

  return html;
}

// Step 3️⃣ 转换执行
const bodyHtml = markdownToHtml(md);

// 顶部 URL 区块（可按需改样式/文案）
const urlBanner = sourceUrl
  ? `<div style="margin:0 0 12px; font-size:12px; opacity:.8;">
       <strong>Source:&nbsp;</strong>
       <a href="${sourceUrl}" target="_blank" rel="noopener noreferrer">${sourceUrl}</a>
     </div>`
  : '';

const html_output = urlBanner + bodyHtml;

return { html_output };

// ✅ 获取节点内容
// 直接获取字符串内容
const tkd = $('Merge').item.json.output || '';
const productTitle = $('Produname').item.json.output || '';
const shert = $json.output || '';
const shortArt = $('SHORART').item.json.output || '';
const aboutFaq = $('ABOUTFAQ').item.json.output || '';

// ✅ 还原被转义的换行符 + 自动补标题换行
function restoreNewlines(text) {
  return (text || '')
    .replace(/\\\\n/g, '\n')        // 还原双层转义
    .replace(/\\n/g, '\n')          // 再还原单层转义
    .replace(/\r\n/g, '\n')         // 统一换行符
    .replace(/(?<!\n)(#{2,5}\s)/g, '\n$1') // 没有换行的标题前加换行
    .replace(/(#+[^\n]+)(?=#+)/g, '$1\n')   // 连续标题之间加换行
    .replace(/\n{3,}/g, '\n\n')     // 最多保留两行空行
    .trim();
}

// ✅ 清理 Markdown 格式（修复版：不再吞掉换行符）
function cleanMarkdown(text) {
  return restoreNewlines(text)
    .replace(/^\s+(?=#+)/gm, '') // 只清理行首的空格，不删除换行
    .trim();
}

// ✅ 拼接（带分隔线）
const merged = [
  cleanMarkdown(tkd),
  cleanMarkdown(productTitle),
  cleanMarkdown(shert),
  cleanMarkdown(shortArt),
  cleanMarkdown(aboutFaq)
].filter(Boolean).join('\n\n---\n\n');

// ✅ 输出
return { merged_output: merged };

