    .map(k => k.trim())
    .filter(Boolean);
} else if (Array.isArray(keywordsRaw)) {
  keywords = keywordsRaw.map(k => k.trim()).filter(Boolean);
}

// 循环替换：把 <strong>关键词</strong> → <span style="color:#ff6600;">关键词</span>
keywords.forEach(keyword => {
  const regex = new RegExp(`<strong>\\s*${keyword}\\s*<\/strong>`, "gi");
  html = html.replace(regex, `<span style="color:#ff6600;">${keyword}</span>`);
});

