let html = $json.html_output || '';

let keywordsRaw = $('Loop Over Items').first().json.property_target_keywords || '';
let keywords = [];

// 支持换行与逗号分隔
if (typeof keywordsRaw === 'string') {
  keywords = keywordsRaw
    .split(/\r?\n|,/) // 同时支持换行或逗号
    .map(k => k.trim())
    .filter(Boolean);
} else if (Array.isArray(keywordsRaw)) {
  keywords = keywordsRaw.map(k => k.trim()).filter(Boolean);
}

// 转义正则特殊字符
function escapeRegExp(str) {
  return str.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
}

// 遍历关键词，替换为彩色高亮 span
keywords.forEach(keyword => {
  const safeKeyword = escapeRegExp(keyword);
  // 你的原始正则：确保不替换标签属性内的词
  const regex = new RegExp(`(?![^<]*>)\\b(${safeKeyword})\\b`, "gi");
  // 如果你需要保持 strong，就用 strong；如果需要加颜色，可以在 style 里加 color
  html = html.replace(regex, `<strong>$1</strong>`);
});

// --- 新增代码开始 ---
// 在最后给整体包一层 div，设置字体为 Arial
// 加上 ,sans-serif 是为了作为后备字体（标准写法）
if (html) {
    html = `<div style="font-family: Arial, sans-serif;">${html}</div>`;
}
// --- 新增代码结束 ---

return { output: html };

